one <- function() {
  fn <- function(x) x[1]^2 + x[2]^2
  heq <- function(x) x[1] + x[2] - 1
  S <- auglag(c(0, 0), fn, heq = heq, localsolver = "COBYLA", deprecatedBehavior = FALSE, control = list(xtol_rel = 1e-8))
  c(S$par, S$value, S$convergence)
}
value <- one()
if (is.character(value) && length(value) == 1) {
  cat(value)
  if (!endsWith(value, "\n")) cat("\n")
} else if (is.logical(value) && length(value) == 1) {
  cat(if (isTRUE(value)) "TRUE\n" else "FALSE\n")
} else {
  cat(paste(sprintf("%.16g", as.numeric(value)), collapse = " "), "\n")
}

